struct unit_of_work {
    std::vector<row*>  added, dirty, removed;
    void flush(db& d) {
        auto tx = d.begin();
        for (auto* r : added)   d.insert(*r);
        for (auto* r : dirty)   d.update(*r);
        for (auto* r : removed) d.erase(*r);
        tx.commit();
        added.clear(); dirty.clear(); removed.clear();
    }
};
